use std::{fs,path::Path,collections::BTreeMap};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-g2-tree-records";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn edit(s:&mut String,old:&str,new:&str,edits:&mut Vec<Value>){assert_eq!(s.matches(old).count(),1);*s=s.replace(old,new);edits.push(json!({"old":old,"new":new}));}
fn main(){let r=Path::new(R);let m=read("/tmp/zopro-grouping-module/production-source-manifest.json");let base=Path::new("/tmp/zopro-poseidon-fused-dot/baseline");for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(base.join(p)),h.as_str().unwrap());assert_eq!(hash(r.join("candidate").join(p)),h.as_str().unwrap());}
 let rel="crates/zopro-core/src/msm.rs";let p=r.join("candidate").join(rel);let original=fs::read_to_string(&p).unwrap();let mut s=original.clone();let mut edits=Vec::new();
 edit(&mut s,"    groups: Vec<Group<C::Base>>,","    groups: Vec<Group<C::Base>>,\n    prefix_records: Vec<[FqBatch; 2]>,",&mut edits);
 edit(&mut s,"            groups: Vec::new(),\n            denominators:","            groups: Vec::new(),\n            prefix_records: Vec::new(),\n            denominators:",&mut edits);
 edit(&mut s,"pub(super) trait BatchInverse: Field {","pub(super) trait BatchInverse: Field {\n    const TREE_PREFIX: bool = false;",&mut edits);
 edit(&mut s,"impl BatchInverse for Fq2 {","impl BatchInverse for Fq2 {\n    const TREE_PREFIX: bool = cfg!(all(feature=\"ifma8\",target_arch=\"x86_64\",target_feature=\"avx512ifma\",target_feature=\"avx512vl\",target_feature=\"avx512dq\",not(no_ifma)));",&mut edits);
 edit(&mut s,"    s.groups.reserve_exact(full / LANES);","    if !F::<C>::TREE_PREFIX {s.groups.reserve_exact(full / LANES);}",&mut edits);
 let begin=s.find("fn reduce_layer<C:").unwrap();let a=s[begin..].find("    for k in (0..full).step_by(LANES) {").unwrap()+begin;let b=s[a..].find("    let mut inverses =").unwrap()+a;let old=s[a..b].to_string();let new=fs::read_to_string(r.join("forward.rs")).unwrap().replace("OLD_FORWARD",&old);edit(&mut s,&old,&new,&mut edits);
 let begin=s.find("fn reduce_layer<C:").unwrap();let a=s[begin..].find("    for (j, group) in s.groups.iter().enumerate().rev() {").unwrap()+begin;let b=s[a..].find("    for k in full..m {").unwrap()+a;let old=s[a..b].to_string();let new=fs::read_to_string(r.join("reverse.rs")).unwrap().replace("OLD_REVERSE",&old);edit(&mut s,&old,&new,&mut edits);
 let tests=fs::read_to_string(r.join("tests.rs")).unwrap();s.push_str(&tests);edits.push(json!({"append":tests}));fs::write(&p,&s).unwrap();
 let mut recovered=s;for e in edits.iter().rev(){if let Some(t)=e["append"].as_str(){assert!(recovered.ends_with(t));recovered.truncate(recovered.len()-t.len());}else{let n=e["new"].as_str().unwrap();assert_eq!(recovered.matches(n).count(),1);recovered=recovered.replace(n,e["old"].as_str().unwrap());}}assert_eq!(recovered,original);
 let changed:Vec<_>=m["source_files_sha256"].as_object().unwrap().iter().filter(|(p,h)|hash(r.join("candidate").join(p))!=h.as_str().unwrap()).map(|(p,_)|p).collect();assert_eq!(changed,vec![rel]);save(r.join("edits.json"),&json!(edits));
 save(r.join("implementation-audit.json"),&json!({"original_files":170,"unchanged_candidate_originals":169,"changed":changed,"original_bytes_recovered":true,"new_module":false,"field_sources_unchanged":true,"new_arithmetic_primitive":false,"new_table_or_plan":false,"new_pool_or_scheduler":false,"production_changed":false,"tree_topology_unchanged":true,"scalar_tail_and_exceptional_compaction_unchanged":true,"native_G2_records_vectors_old_new":[9,2],"new_empty_vector_header_bytes_64bit":24,"fresh_control_reused_unchanged":true}));
 let old="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-25-operation-model";let mut contextpins=BTreeMap::new();for f in ["README.md","results.json","instrumentation-audit.json","source/crates/zopro-core/src/msm.rs"]{let p=format!("{old}/{f}");contextpins.insert(p.clone(),hash(p));}let oldsource=fs::read_to_string(format!("{old}/source/crates/zopro-core/src/msm.rs")).unwrap();assert!(oldsource.contains("if m==0{crate::operation_census::event(16,1);}"));save(r.join("context-audit.json"),&json!({"pins":contextpins,"counter_checks_actual_m_zero":true,"historical_primary_empty_tree_batches":0,"no_empty_inverse_variant_built":true,"prior_generic_G2_prefix_tree_left_existing_weighted_top_reduce_layer_unchanged":true}));
 let mut plan:Value=serde_json::from_str(&serde_json::to_string(&read("/tmp/zopro-poseidon-fused-dot/native-plan.json")).unwrap().replace("/tmp/zopro-poseidon-fused-dot",R)).unwrap();let steps=plan["steps"].as_array_mut().unwrap();steps.retain(|x|!["fresh","fresh-libraries"].contains(&x["name"].as_str().unwrap()));for x in steps{if x["name"]=="core"{x["required_tests"]=json!(["msm::tree_prefix_tests::prefix_tree_complete_pairs_tails_and_reuse"]);}if x["name"]=="fused"{x["name"]=json!("tree");}}save(r.join("native-plan.json"),&plan);
 let mut e=fs::read_to_string("/tmp/zopro-fused-top/experiment.rs").unwrap().replace("/tmp/zopro-fused-top",R).replace("combined","tree").replace("/tmp/zopro-arithmetic-leaves-corrected/tree-proof-inventory.json","/tmp/zopro-arithmetic-leaves-corrected/combined-proof-inventory.json");
 e=e.replace("\"/tmp/zopro-arithmetic-leaves-corrected/combined-proof-inventory.json\"]","\"/tmp/zopro-arithmetic-leaves-corrected/combined-proof-inventory.json\",\"/tmp/zopro-fused-top/proof-inventory.json\"]");
 for(old,new)in [("7233","OLD_PRIOR"),("7242","OLD_PRE"),("7260","OLD_SCREEN"),("7473","OLD_FULL")] {e=e.replace(old,new);}for(old,new)in [("OLD_PRIOR","7260"),("OLD_PRE","7269"),("OLD_SCREEN","7287"),("OLD_FULL","7500")] {e=e.replace(old,new);}
 e=e.replace("[\"setup.rs\",\"experiment.rs\",\"design.md\",\"top.rs\",\"edits.json\",\"implementation-audit.json\",\"native-plan.json\"]","[\"setup.rs\",\"experiment.rs\",\"design.md\",\"forward.rs\",\"reverse.rs\",\"tests.rs\",\"context-audit.json\",\"edits.json\",\"implementation-audit.json\",\"native-plan.json\"]");e=e.replace("Frozen tree K/H top,168originals exact; unchanged field; native110expected","Frozen G2 existing-tree prefix records,169originals exact; native110expected");
 assert!(!e.contains("top.rs"));fs::write(r.join("experiment.rs"),e).unwrap();println!("Generated one-file G2 tree-record candidate, reversible source audit, native plan and SDK protocol");
}
